async function huntHigherLevel() {
    const targets = [
        { name: 'Goblin', loc: [3215, 3205] },
        { name: 'Cow', loc: [3210, 3210] },
        { name: 'Chicken', loc: [3225, 3215] },
        { name: 'Imp', loc: [3210, 3215] },
        { name: 'Butterfly', loc: [3222, 3217] }
    ];

    for (const target of targets) {
        await bot.walkTo(target.loc[0], target.loc[1]);
        const res = await bot.attack(target.name);
        if (res.success) {
            while (sdk.getState()?.player?.combat.inCombat) {
                if (sdk.getState()?.player?.hp < 8) {
                    await bot.eatFood();
                }
                await sdk.waitForStateUpdate();
            }
        }
    }
}
await huntHigherLevel();

